import React from 'react';
import { motion } from "framer-motion";
import { useDispatch } from "react-redux";
import { toggleReadStatus, removeBook } from "./store/booksSlice";
import s from './BookItem.module.css';

type Book = {
    id: string;
    title: string;
    author: string;
    isRead: boolean;
    category: string;
    fileUrl?: string;
};

type BookItemProps = {
    book: Book;
};

export const BookItem: React.FC<BookItemProps> = ({ book }) => {
    const dispatch = useDispatch();

    return (
        <motion.div
            initial={{ opacity: 0, x: -50 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 50 }}
            transition={{ duration: 0.5 }}
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            className={s.bookItem}
        >
            <p className={s.bookTitle}>Title: {book.title}</p>
            <p className={s.bookAuthor}>Author: {book.author}</p>
            <p>Read: {book.isRead ? "Yes" : "No"}</p>
            <p className={s.bookCategory}>Category: {book.category}</p>
            {book.fileUrl && (
                <a href={book.fileUrl} target="_blank" rel="noopener noreferrer">
                    Read Book
                </a>
            )}
            <button
                onClick={() => dispatch(toggleReadStatus(book.id))}
                className={`${s.button} ${book.isRead ? s.read : s.unread}`}
            >
                {book.isRead ? "Mark as Unread" : "Mark as Read"}
            </button>
            <button
                onClick={() => dispatch(removeBook(book.id))}
                className={`${s.button} ${s.remove}`}
            >
                Remove this book
            </button>
        </motion.div>
    );
};
