import React from "react";
import { Link } from "react-router-dom";
import { useAuthState } from "react-firebase-hooks/auth";
import { auth } from "./firebase/firebase";
import s from "./Header.module.css";

export const Header = () => {
    const [user] = useAuthState(auth);

    return (
        <header className={s.header}>
            <div className={s.logo}>
                <Link to="/" className={s.logoText}>
                    Space Library
                </Link>
            </div>
            <nav className={s.nav}>
                <Link to="/" className={s.navLink}>Home</Link>
                <Link to="/library" className={s.navLink}>Library</Link>
                {!user ? (
                    <>
                        <Link to="/signup" className={s.navLink}>Sign Up</Link>
                        <Link to="/login" className={s.navLink}>Log In</Link>
                    </>
                ) : (
                    <button
                        onClick={() => auth.signOut()}
                        className={s.logoutButton}
                    >
                        Log Out
                    </button>
                )}
            </nav>
        </header>
    );
};

